				const accountLabel = (id) => {
					const hit = (Array.isArray(lastAccountsPayload?.accounts) ? lastAccountsPayload.accounts : []).find((item) => item.id === id);
					return hit ? String(hit.label || hit.display || hit.id) : id;
				};
				/**
				* 按天趋势图。手写 SVG（不引图表库）。
				* 左轴是 token、右轴是调用次数 —— 两把尺子只共用画布，不共用刻度（把它们画在同一
				* 坐标系里是最常见的图表错误：量级差几百倍时折线会贴死在底部）。
				*/
				const trendSvg = (series) => {
					const W = 640;
					const H = 170;
					const padL = 46;
					const plotW = 564;
					const plotH = 142;
					const n = Math.max(1, series.length);
					const tokenOf = (d) => (Number(d?.in) || 0) + (Number(d?.out) || 0);
					const maxTok = Math.max(1, ...series.map(tokenOf));
					const maxCalls = Math.max(1, ...series.map((d) => Number(d?.calls) || 0));
					const niceMax = (value) => {
						const base = Math.pow(10, Math.floor(Math.log10(value)));
						const norm = value / base;
						return (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 5 ? 5 : 10) * base;
					};
					const top = niceMax(maxTok);
					const slot = plotW / n;
					const barW = Math.max(1.5, slot * .62);
					let out = T(`<svg class="dsw-trend" viewBox="0 0 ${W} ${H}" role="img" aria-label="按天用量趋势">`);
					for (const ratio of [
						0,
						.5,
						1
					]) {
						const y = 152 - plotH * ratio;
						out += `<line class="grid" x1="${padL}" y1="${y.toFixed(1)}" x2="610" y2="${y.toFixed(1)}"></line>`;
						out += `<text class="axis" x="41" y="${(y + 3).toFixed(1)}" text-anchor="end">${fmtTokens(top * ratio)}</text>`;
					}
					series.forEach((d, i) => {
						const x = padL + slot * i + (slot - barW) / 2;
						const hIn = (Number(d?.in) || 0) / top * plotH;
						const hOut = (Number(d?.out) || 0) / top * plotH;
						const yIn = 152 - hIn;
						out += T(`<g><title>${d?.date}：总 ${fullNum(tokenOf(d))} · 输入 ${fullNum(Number(d?.in) || 0)} / 输出 ${fullNum(Number(d?.out) || 0)} · 调用 ${Number(d?.calls) || 0} 次</title>`);
						if (hIn > 0) out += `<rect class="bar-in" x="${x.toFixed(1)}" y="${yIn.toFixed(1)}" width="${barW.toFixed(1)}" height="${hIn.toFixed(1)}" rx="1"></rect>`;
						if (hOut > 0) out += `<rect class="bar-out" x="${x.toFixed(1)}" y="${(yIn - hOut).toFixed(1)}" width="${barW.toFixed(1)}" height="${hOut.toFixed(1)}" rx="1"></rect>`;
						if (hIn + hOut <= 0 && (Number(d?.calls) || 0) > 0) out += `<rect class="bar-out" x="${x.toFixed(1)}" y="${150 .toFixed(1)}" width="${barW.toFixed(1)}" height="2" rx="0.5"></rect>`;
						out += "</g>";
					});
					const points = series.map((d, i) => {
						const x = padL + slot * i + slot / 2;
						const y = 152 - (Number(d?.calls) || 0) / maxCalls * plotH;
						return `${x.toFixed(1)},${y.toFixed(1)}`;
					}).join(" ");
					out += `<polyline class="line" points="${points}"></polyline>`;
					out += `<text class="axis" x="614" y="${13 .toFixed(1)}" text-anchor="start">${Math.round(maxCalls)}</text>`;
					out += `<text class="axis" x="614" y="${155 .toFixed(1)}" text-anchor="start">0</text>`;
					const labelStep = Math.max(1, Math.ceil(n / 6));
					series.forEach((d, i) => {
						if (i % labelStep !== 0 && i !== n - 1) return;
						const x = padL + slot * i + slot / 2;
						const parts = String(d?.date ?? "").split("-");
						out += `<text class="axis" x="${x.toFixed(1)}" y="165" text-anchor="middle">${Number(parts[1])}/${Number(parts[2])}</text>`;
					});
					out += "</svg>";
					return out;
				};
				/** 分布排行。条宽按**最大值**归一 —— 按总量归一的话只有第一名看得见，其余全是一根短刺。 */
